function isPidAlive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

function tryAcquireBotInstanceLock(): boolean {
  try {
    fs.writeFileSync(BOT_INSTANCE_LOCK_FILE, String(process.pid), { encoding: "utf8", flag: "wx" });
    botInstanceLockAcquired = true;
    return true;
  } catch {
    try {
      const existingRaw = fs.readFileSync(BOT_INSTANCE_LOCK_FILE, "utf8").trim();
      const existingPid = Number(existingRaw);
      if (Number.isFinite(existingPid) && existingPid > 0 && !isPidAlive(existingPid)) {
        fs.unlinkSync(BOT_INSTANCE_LOCK_FILE);
        fs.writeFileSync(BOT_INSTANCE_LOCK_FILE, String(process.pid), { encoding: "utf8", flag: "wx" });
        botInstanceLockAcquired = true;
        return true;
      }
    } catch {
      // ignore stale/invalid lock recovery failures
    }
    return false;
  }
}

function releaseBotInstanceLock(): void {
  if (!botInstanceLockAcquired) return;
  try {
    const existingRaw = fs.readFileSync(BOT_INSTANCE_LOCK_FILE, "utf8").trim();
    if (Number(existingRaw) === process.pid) {
      fs.unlinkSync(BOT_INSTANCE_LOCK_FILE);
    }
  } catch {
    // ignore cleanup errors
  }
  botInstanceLockAcquired = false;
}

function canUsePrefixCommand(interaction: any): boolean {
  if (interaction.user?.id === PREFIX_COMMAND_ALLOWED_USER_ID) return true;

  const username = (interaction.user?.username || "").toLowerCase();
  const globalName = (interaction.user?.globalName || "").toLowerCase();
  const nickname = ((interaction.member as any)?.nickname || "").toLowerCase();

  return username.includes("brian") || globalName.includes("brian") || nickname.includes("brian");
}

function parseDashboardConfigObject(raw: unknown): Record<string, unknown> {
  if (typeof raw !== "string") return {};

  try {
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return {};
    }
    return parsed as Record<string, unknown>;
  } catch {
    return {};
  }
}

function isGuildConfigDisabled(config?: any): boolean {
  const parsed = parseDashboardConfigObject(config?.customCategoryPings);
  return parsed[DASHBOARD_BOT_DISABLED_KEY] === true;
}

function getDashboardFeatureFlagOverrides(config?: any): Record<string, boolean> {
  const parsed = parseDashboardConfigObject(config?.customCategoryPings);
  const rawFlags = parsed[DASHBOARD_FEATURE_FLAGS_KEY];
  if (!rawFlags || typeof rawFlags !== "object" || Array.isArray(rawFlags)) {
    return {};
  }

  const result: Record<string, boolean> = {};
  for (const [key, value] of Object.entries(rawFlags as Record<string, unknown>)) {
    if (typeof value === "boolean") {
      result[key] = value;
    }
  }
  return result;
}

function getDashboardDefaultFeatureEnabledMap(_config?: any): Record<string, boolean> {
  return {
    modmail: true,
    appeals: true,
    payouts: true,
    moderation: true,
    quiz: true,
    "staff-intro": true,
    inactivity: true,
    permissions: true,
    embeds: true,
    advanced: true,
    "role-requests": true,
    "ban-requests": true,
    activity: true,
    roster: true,
    snippets: true,
    sticky: true,
    "auto-roles": true,
    "reaction-roles": true,
  };
}

function isDashboardFeatureEnabled(config: any, featureId: string): boolean {
  const normalizedFeatureId = String(featureId || "").trim();
  if (!normalizedFeatureId) return true;

  const overrides = getDashboardFeatureFlagOverrides(config);
  if (typeof overrides[normalizedFeatureId] === "boolean") {
    return overrides[normalizedFeatureId];
  }

  const defaults = getDashboardDefaultFeatureEnabledMap(config);
  if (typeof defaults[normalizedFeatureId] === "boolean") {
    return defaults[normalizedFeatureId];
  }

  return true;
}

type SecurityPunishmentType = "ban" | "kick" | "clear_roles";
type SecurityRuleKey =
  | "antiBan"
  | "antiKick"
  | "antiBotAdd"
  | "antiRoleUpdate"
  | "antiRoleAdd"
  | "antiChannelCreate"
  | "antiChannelDelete"
  | "antiRoleCreate"
  | "antiRoleDelete";

type SecurityRuleConfig = {
  threshold: number;
  punishmentType: SecurityPunishmentType;
  timeWindowSeconds: number;
  enabled: boolean;
  whitelistedRoleIds: string[];
  whitelistedUserIds: string[];
};

type DashboardSecuritySettings = {
  rules: Record<SecurityRuleKey, SecurityRuleConfig>;
  logChannelId: string | null;
  whitelistedRoleIds: string[];
  whitelistedUserIds: string[];
  accessRoleIds: string[];
  accessUserIds: string[];
};

type DashboardBlacklistEntry = {
  blacklistedById: string;
  reason: string | null;
  createdAt: string | null;
};

const SECURITY_RULE_LABELS: Record<SecurityRuleKey, string> = {
  antiBan: "Anti Ban",
  antiKick: "Anti Kick",
  antiBotAdd: "Anti Bot Add",
  antiRoleUpdate: "Anti Role Update",
  antiRoleAdd: "Anti Role Add",
  antiChannelCreate: "Anti Channel Create",
  antiChannelDelete: "Anti Channel Delete",
  antiRoleCreate: "Anti Role Create",
  antiRoleDelete: "Anti Role Delete",
};

const SECURITY_REASON_LABELS: Record<SecurityRuleKey, string> = {
  antiBan: "Banning Members",
  antiKick: "Kicking Members",
  antiBotAdd: "Adding Bots",
  antiRoleUpdate: "Updating Roles",
  antiRoleAdd: "Giving Administrator Roles",
  antiChannelCreate: "Creating Channels",
  antiChannelDelete: "Deleting Channels",
  antiRoleCreate: "Creating Roles",
  antiRoleDelete: "Deleting Roles",
};

const securityActionTracker = new Map<string, { count: number; startedAt: number }>();

function createDefaultDashboardSecuritySettings(): DashboardSecuritySettings {
  return {
    rules: {
      antiBan: { threshold: 3, punishmentType: "kick", timeWindowSeconds: DEFAULT_SECURITY_TIME_WINDOW_SECONDS, enabled: false, whitelistedRoleIds: [], whitelistedUserIds: [] },
      antiKick: { threshold: 3, punishmentType: "kick", timeWindowSeconds: DEFAULT_SECURITY_TIME_WINDOW_SECONDS, enabled: false, whitelistedRoleIds: [], whitelistedUserIds: [] },
      antiBotAdd: { threshold: 1, punishmentType: "ban", timeWindowSeconds: DEFAULT_SECURITY_TIME_WINDOW_SECONDS, enabled: false, whitelistedRoleIds: [], whitelistedUserIds: [] },
      antiRoleUpdate: { threshold: 3, punishmentType: "clear_roles", timeWindowSeconds: DEFAULT_SECURITY_TIME_WINDOW_SECONDS, enabled: false, whitelistedRoleIds: [], whitelistedUserIds: [] },
      antiRoleAdd: { threshold: 3, punishmentType: "clear_roles", timeWindowSeconds: DEFAULT_SECURITY_TIME_WINDOW_SECONDS, enabled: false, whitelistedRoleIds: [], whitelistedUserIds: [] },
      antiChannelCreate: { threshold: 3, punishmentType: "kick", timeWindowSeconds: DEFAULT_SECURITY_TIME_WINDOW_SECONDS, enabled: false, whitelistedRoleIds: [], whitelistedUserIds: [] },
      antiChannelDelete: { threshold: 2, punishmentType: "ban", timeWindowSeconds: DEFAULT_SECURITY_TIME_WINDOW_SECONDS, enabled: false, whitelistedRoleIds: [], whitelistedUserIds: [] },
      antiRoleCreate: { threshold: 3, punishmentType: "kick", timeWindowSeconds: DEFAULT_SECURITY_TIME_WINDOW_SECONDS, enabled: false, whitelistedRoleIds: [], whitelistedUserIds: [] },
      antiRoleDelete: { threshold: 2, punishmentType: "ban", timeWindowSeconds: DEFAULT_SECURITY_TIME_WINDOW_SECONDS, enabled: false, whitelistedRoleIds: [], whitelistedUserIds: [] },
    },
    logChannelId: null,
    whitelistedRoleIds: [],
    whitelistedUserIds: [],
    accessRoleIds: [],
    accessUserIds: [],
  };
}

function normalizeSecurityStringList(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return Array.from(new Set(value.map((entry) => String(entry || "").trim()).filter(Boolean)));
}

function getDashboardSecuritySettings(config?: any): DashboardSecuritySettings {
  const parsed = parseDashboardConfigObject(config?.customCategoryPings);
  const raw = parsed[DASHBOARD_SECURITY_SETTINGS_KEY];
  const securityObject = raw && typeof raw === "object" && !Array.isArray(raw)
    ? raw as Record<string, unknown>
    : {};
  const defaults = createDefaultDashboardSecuritySettings();
  const rulesRaw = securityObject.rules && typeof securityObject.rules === "object" && !Array.isArray(securityObject.rules)
    ? securityObject.rules as Record<string, unknown>
    : {};

  const rules = (Object.keys(defaults.rules) as SecurityRuleKey[]).reduce<Record<SecurityRuleKey, SecurityRuleConfig>>((acc, ruleKey) => {
    const ruleRaw = rulesRaw[ruleKey];
    const ruleObject = ruleRaw && typeof ruleRaw === "object" && !Array.isArray(ruleRaw)
      ? ruleRaw as Record<string, unknown>
      : {};
    const thresholdValue = Number(ruleObject.threshold);
    const timeWindowValue = Number(ruleObject.timeWindowSeconds);
    const punishmentRaw = typeof ruleObject.punishmentType === "string" ? ruleObject.punishmentType : defaults.rules[ruleKey].punishmentType;

    acc[ruleKey] = {
      enabled: ruleObject.enabled === true,
      threshold: Number.isFinite(thresholdValue) && thresholdValue > 0
        ? Math.max(1, Math.min(50, Math.round(thresholdValue)))
        : defaults.rules[ruleKey].threshold,
      punishmentType: punishmentRaw === "ban" || punishmentRaw === "kick" || punishmentRaw === "clear_roles"
        ? punishmentRaw
        : defaults.rules[ruleKey].punishmentType,
      timeWindowSeconds: Number.isFinite(timeWindowValue) && timeWindowValue > 0
        ? Math.max(5, Math.min(3600, Math.round(timeWindowValue)))
        : defaults.rules[ruleKey].timeWindowSeconds,
      whitelistedRoleIds: normalizeSecurityStringList(ruleObject.whitelistedRoleIds),
      whitelistedUserIds: normalizeSecurityStringList(ruleObject.whitelistedUserIds),
    };
    return acc;
  }, {} as Record<SecurityRuleKey, SecurityRuleConfig>);

  return {
    rules,
    logChannelId: typeof securityObject.logChannelId === "string" && securityObject.logChannelId.trim()
      ? securityObject.logChannelId.trim()
      : null,
    whitelistedRoleIds: normalizeSecurityStringList(securityObject.whitelistedRoleIds),
    whitelistedUserIds: normalizeSecurityStringList(securityObject.whitelistedUserIds),
    accessRoleIds: normalizeSecurityStringList(securityObject.accessRoleIds),
    accessUserIds: normalizeSecurityStringList(securityObject.accessUserIds),
  };
}

function getDashboardBlacklistedUsers(config?: any): Record<string, DashboardBlacklistEntry> {
  const parsed = parseDashboardConfigObject(config?.customCategoryPings);
  const raw = parsed[DASHBOARD_BLACKLIST_USERS_KEY];
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    return {};
  }

  const result: Record<string, DashboardBlacklistEntry> = {};
  for (const [userId, value] of Object.entries(raw as Record<string, unknown>)) {
    if (!value || typeof value !== "object" || Array.isArray(value)) continue;
    const entry = value as Record<string, unknown>;
    result[userId] = {
      blacklistedById: String(entry.blacklistedById || ""),
      reason: typeof entry.reason === "string" ? entry.reason : null,
      createdAt: typeof entry.createdAt === "string" ? entry.createdAt : null,
    };
  }

  return result;
}

function getSecurityRuleLabel(ruleKey: SecurityRuleKey): string {
  return SECURITY_RULE_LABELS[ruleKey] || ruleKey;
}

function getSecurityPunishmentLabel(punishmentType: SecurityPunishmentType): string {
  switch (punishmentType) {
    case "ban":
      return "Ban";
    case "kick":
      return "Kick";
    case "clear_roles":
      return "Clear Roles";
    default:
      return punishmentType;
  }
}

function getSecurityReasonLabel(ruleKey: SecurityRuleKey): string {
  return SECURITY_REASON_LABELS[ruleKey] || getSecurityRuleLabel(ruleKey);
}

function roleHasAdministratorPermission(role: any): boolean {
  try {
    const bitfield = role?.permissions?.bitfield;
    const permissionBits = typeof bitfield === "bigint"
      ? bitfield
      : BigInt(String(bitfield ?? 0));
    return (permissionBits & PermissionFlagsBits.Administrator) === PermissionFlagsBits.Administrator;
  } catch {
    return false;
  }
}

async function pause(ms: number): Promise<void> {
  await new Promise((resolve) => setTimeout(resolve, ms));
}

async function findRecentAuditEntry(
  guild: any,
  type: AuditLogEvent,
  predicate: (entry: any) => boolean,
  limit = 6,
  maxAgeMs = 20_000,
): Promise<any | null> {
  for (let attempt = 0; attempt < 3; attempt += 1) {
    try {
      const logs = await guild.fetchAuditLogs({ limit, type });
      const entry = logs.entries.find((candidate: any) => {
        const createdTimestamp = Number(candidate?.createdTimestamp || 0);
        return createdTimestamp > 0 && (Date.now() - createdTimestamp) <= maxAgeMs && predicate(candidate);
      });
      if (entry) return entry;
    } catch {
      return null;
    }

    if (attempt < 2) {
      await pause(SECURITY_AUDIT_LOOKUP_DELAY_MS);
    }
  }

  return null;
}

function bumpSecurityActionCount(
  guildId: string,
  executorId: string,
  ruleKey: SecurityRuleKey,
  threshold: number,
  timeWindowSeconds: number,
) {
  const key = `${guildId}:${executorId}:${ruleKey}`;
  const now = Date.now();
  const timeWindowMs = Math.max(5, Math.min(3600, timeWindowSeconds)) * 1000;
  const existing = securityActionTracker.get(key);
  const withinWindow = !!existing && (now - existing.startedAt) <= timeWindowMs;
  const count = withinWindow ? existing!.count + 1 : 1;
  const startedAt = withinWindow ? existing!.startedAt : now;
  securityActionTracker.set(key, { count, startedAt });

  const thresholdReached = count >= Math.max(1, threshold);
  if (thresholdReached) {
    securityActionTracker.delete(key);
  }

  return {
    count,
    thresholdReached,
    remainingAttempts: Math.max(0, Math.max(1, threshold) - count),
    timeWindowMs,
  };
}

async function sendSecurityLog(guild: any, config: any, securitySettings: DashboardSecuritySettings, embed: EmbedBuilder) {
  const channelId = securitySettings.logChannelId || config?.modLogChannelId || config?.commandLogChannelId || config?.logChannelId;
  if (!channelId) return;

  try {
    const logChannel = await safeChannelFetch(channelId);
    if (logChannel && "send" in logChannel) {
      await logChannel.send({ embeds: [embed] });
    }
  } catch (error) {
    console.log("[SECURITY] Failed to send security log:", error);
  }
}

const blacklistSweepInProgress = new Set<string>();

async function enforceBlacklistedUserBan(
  guild: any,
  userId: string | null | undefined,
  entry: DashboardBlacklistEntry | null | undefined,
  context: string,
): Promise<boolean> {
  const normalizedUserId = String(userId || "").trim();
  if (!normalizedUserId || normalizedUserId === client.user?.id) {
    return false;
  }

  const reasonParts = ["Dashboard blacklist enforcement"];
  if (entry?.reason) {
    reasonParts.push(entry.reason);
  }
  if (context) {
    reasonParts.push(context);
  }
  const reason = reasonParts.join(" • ").slice(0, 512);

  let lastError: unknown = null;
  for (let index = 0; index < BLACKLIST_REBAN_RETRY_DELAYS_MS.length; index += 1) {
    const delayMs = BLACKLIST_REBAN_RETRY_DELAYS_MS[index];
    if (delayMs > 0) {
      await pause(delayMs);
    }

    try {
      await guild.members.ban(normalizedUserId, { reason, deleteMessageSeconds: 0 });
      console.log(`[BLACKLIST] Enforced blacklist on ${normalizedUserId} in guild ${guild.id} (${context}) on attempt ${index + 1}`);
      return true;
    } catch (error) {
      lastError = error;
    }
  }

  console.log(`[BLACKLIST] Failed to enforce blacklist on ${normalizedUserId} in guild ${guild.id}:`, lastError);
  return false;
}

async function enforceGuildBlacklistState(guild: any): Promise<void> {
  const guildId = String(guild?.id || "").trim();
  if (!guildId || blacklistSweepInProgress.has(guildId)) {
    return;
  }

  blacklistSweepInProgress.add(guildId);
  try {
    const config = await storage.getGuildConfig(guildId).catch(() => null);
    const blacklistedUsers = getDashboardBlacklistedUsers(config);
    const entries = Object.entries(blacklistedUsers);
    if (entries.length === 0) {
      return;
    }

    for (const [userId, entry] of entries) {
      const activeBan = await guild.bans.fetch(userId).catch(() => null);
      if (activeBan) {
        continue;
      }

      await enforceBlacklistedUserBan(
        guild,
        userId,
        entry,
        "watchdog sweep detected a missing blacklist ban",
      );
    }
  } finally {
    blacklistSweepInProgress.delete(guildId);
  }
}

async function enforceAllGuildBlacklistState(): Promise<void> {
  const guilds = Array.from(client.guilds.cache.values());
  for (const guild of guilds) {
    await enforceGuildBlacklistState(guild).catch((error) => {
      console.log(`[BLACKLIST] Watchdog sweep failed for guild ${guild.id}:`, error);
    });
  }
}

async function handleSecurityTrigger(
  guild: any,
  executorId: string | null | undefined,
  ruleKey: SecurityRuleKey,
  details: string,
  targetId?: string | null,
) {
  const normalizedExecutorId = String(executorId || "").trim();
  if (!normalizedExecutorId || normalizedExecutorId === client.user?.id) {
    return;
  }

  const config = await storage.getGuildConfig(guild.id).catch(() => null);
  const securitySettings = getDashboardSecuritySettings(config);
  const rule = securitySettings.rules[ruleKey];
  if (!rule?.enabled) {
    return;
  }

  if (securitySettings.whitelistedUserIds.includes(normalizedExecutorId)) {
    return;
  }

  const executorMember = await guild.members.fetch(normalizedExecutorId).catch(() => null);
  const executorRoleIds = executorMember ? Array.from(executorMember.roles.cache.keys()) : [];
  if (securitySettings.whitelistedRoleIds.some((roleId) => executorRoleIds.includes(roleId))) {
    return;
  }

  if ((rule.whitelistedUserIds || []).includes(normalizedExecutorId)) {
    return;
  }

  if ((rule.whitelistedRoleIds || []).some((roleId) => executorRoleIds.includes(roleId))) {
    return;
  }

  const { count, thresholdReached, remainingAttempts, timeWindowMs } = bumpSecurityActionCount(
    guild.id,
    normalizedExecutorId,
    ruleKey,
    rule.threshold,
    rule.timeWindowSeconds,
  );

  const userFieldValue = executorMember
    ? `${executorMember.user.tag}\n\`${normalizedExecutorId}\``
    : `<@${normalizedExecutorId}>\n\`${normalizedExecutorId}\``;
  const targetFieldValue = targetId && targetId !== normalizedExecutorId
    ? `<@${targetId}>\n\`${targetId}\``
    : null;
  const thresholdLabel = `${count}/${Math.max(1, rule.threshold)} action(s)`;
  const timeWindowLabel = `${Math.round(timeWindowMs / 1000)} second(s)`;

  if (!thresholdReached) {
    const warningEmbed = new EmbedBuilder()
      .setTitle("User Warning")
      .setColor(0xfaa61a)
      .addFields(
        { name: "User:", value: userFieldValue, inline: false },
        ...(targetFieldValue ? [{ name: "Target:", value: targetFieldValue, inline: false }] : []),
        { name: "Reason:", value: getSecurityReasonLabel(ruleKey), inline: false },
        { name: "Threshold:", value: thresholdLabel, inline: false },
        { name: "Remaining Attempts:", value: `${remainingAttempts}`, inline: false },
        { name: "Time:", value: timeWindowLabel, inline: false },
      )
      .setFooter({ text: details.slice(0, 200) || "Security warning issued." })
      .setTimestamp();

    await sendSecurityLog(guild, config, securitySettings, warningEmbed);
    return;
  }

  const reason = `${getSecurityRuleLabel(ruleKey)} threshold reached in ${guild.name}`;
  let resultSummary = "No action taken.";
  let actionSucceeded = false;

  try {
    if (guild.ownerId === normalizedExecutorId) {
      resultSummary = "Detected, but the server owner cannot be punished automatically.";
    } else if (!executorMember) {
      resultSummary = "Detected, but the member could not be resolved in the guild.";
    } else if (rule.punishmentType === "ban") {
      if (!executorMember.bannable) {
        resultSummary = "Detected, but the member is above the bot or cannot be banned.";
      } else {
        await executorMember.ban({ reason });
        resultSummary = `Banned <@${normalizedExecutorId}>.`;
        actionSucceeded = true;
      }
    } else if (rule.punishmentType === "kick") {
      if (!executorMember.kickable) {
        resultSummary = "Detected, but the member is above the bot or cannot be kicked.";
      } else {
        await executorMember.kick(reason);
        resultSummary = `Kicked <@${normalizedExecutorId}>.`;
        actionSucceeded = true;
      }
    } else {
      const removableRoleIds = executorMember.roles.cache
        .filter((role: any) => role.id !== guild.id && role.editable)
        .map((role: any) => role.id);

      if (removableRoleIds.length === 0) {
        resultSummary = "Detected, but there were no removable roles on the member.";
      } else {
        await executorMember.roles.remove(removableRoleIds, reason);
        resultSummary = `Cleared ${removableRoleIds.length} role(s) from <@${normalizedExecutorId}>.`;
        actionSucceeded = true;
      }
    }
  } catch (error: any) {
    resultSummary = `Attempted ${getSecurityPunishmentLabel(rule.punishmentType)}, but it failed: ${error?.message || "Unknown error"}`;
  }

  const punishedEmbed = new EmbedBuilder()
    .setTitle(actionSucceeded ? "User Punished" : "Punishment Blocked")
    .setColor(actionSucceeded ? 0xed4245 : 0xfaa61a)
    .setDescription(
      actionSucceeded
        ? `<@${normalizedExecutorId}> hit the **${getSecurityRuleLabel(ruleKey)}** threshold and the configured punishment was applied.`
        : `<@${normalizedExecutorId}> hit the **${getSecurityRuleLabel(ruleKey)}** threshold, but the punishment could not be completed.`
    )
    .addFields(
      { name: "User:", value: userFieldValue, inline: false },
      ...(targetFieldValue ? [{ name: "Target:", value: targetFieldValue, inline: false }] : []),
      { name: "Reason:", value: getSecurityReasonLabel(ruleKey), inline: false },
      { name: "Threshold:", value: thresholdLabel, inline: true },
      { name: "Punishment Type:", value: getSecurityPunishmentLabel(rule.punishmentType), inline: true },
      { name: "Time Window:", value: timeWindowLabel, inline: true },
      { name: actionSucceeded ? "Result:" : "Why it failed:", value: resultSummary.slice(0, 1024), inline: false },
    )
    .setFooter({ text: details.slice(0, 200) || "Security punishment applied." })
    .setTimestamp();

  await sendSecurityLog(guild, config, securitySettings, punishedEmbed);
}

function getRequiredDashboardFeatureForCommand(commandName: string, subcommand: string | null): string | null {
  if (commandName === "edit" && subcommand === "embed") {
    return "embeds";
  }

  return DASHBOARD_FEATURE_COMMAND_MAP[commandName] || null;
}

function getRequiredDashboardFeatureForCustomId(customId: string | null | undefined): string | null {
  const normalized = String(customId || "").trim();
  if (!normalized) return null;

  if (normalized.startsWith("ticket_invite_accept_") || normalized.startsWith("ticket_invite_deny_")) {
    return null;
  }

  const exactMatches: Record<string, string> = {
    request_payout: "payouts",
    payout_modal: "payouts",
    submit_ban_request: "ban-requests",
    submit_unban_request: "ban-requests",
    submit_kick_request: "ban-requests",
    ban_request_modal: "ban-requests",
    unban_request_modal: "ban-requests",
    kick_request_modal: "ban-requests",
    promotion_request_open_promotion: "moderation",
    promotion_request_open_demotion: "moderation",
    promotion_request_modal_promotion: "moderation",
    promotion_request_modal_demotion: "moderation",
  };

  if (exactMatches[normalized]) {
    return exactMatches[normalized];
  }

  const prefixMatches: Array<[string, string]> = [
    ["ticket_custom_modal::", "modmail"],
    ["dm_ticket_modal_", "modmail"],
    ["ticket_select_", "modmail"],
    ["ticket_modal_", "modmail"],
    ["ticket_", "modmail"],
    ["appeal_start_", "appeals"],
    ["config_appeal_modal_", "appeals"],
    ["start_staff_application_", "staff-intro"],
    ["staff_app_terminate_", "staff-intro"],
    ["staff_app_approve_", "staff-intro"],
    ["staff_app_deny_", "staff-intro"],
    ["staff_app_modlogs_", "staff-intro"],
    ["config_staffintro_modal_", "staff-intro"],
    ["config_staffapplications_modal_", "staff-intro"],
    ["start_quiz_", "quiz"],
    ["terminate_quizzes_", "quiz"],
    ["quiz_terminate_", "quiz"],
    ["quiz_approve_", "quiz"],
    ["quiz_deny_", "quiz"],
    ["quiz_review_", "quiz"],
    ["request_inactivity_", "inactivity"],
    ["inactivity_submit_", "inactivity"],
    ["inactivity_approve_", "inactivity"],
    ["inactivity_deny_", "inactivity"],
    ["inactivity_review_", "inactivity"],
    ["config_inactivity_modal_", "inactivity"],
    ["approve_", "payouts"],
    ["deny_", "payouts"],
    ["action_reason_", "payouts"],
    ["role_request_review_", "role-requests"],
    ["role_request_reviewer_", "role-requests"],
    ["role_request_action_", "role-requests"],
    ["role_request_approve_", "role-requests"],
    ["role_request_deny_", "role-requests"],
    ["ban_approve_", "ban-requests"],
    ["ban_deny_", "ban-requests"],
    ["kick_approve_", "ban-requests"],
    ["kick_deny_", "ban-requests"],
    ["unban_approve_", "ban-requests"],
    ["unban_deny_", "ban-requests"],
    ["promotion_request_", "moderation"],
    ["promotion_request_action_", "moderation"],
    ["config_modmail_modal_", "modmail"],
    ["config_welcome_modal_", "embeds"],
    ["send_embed_modal_", "embeds"],
    ["rrselect:", "reaction-roles"],
    ["rrbtn:", "reaction-roles"],
  ];

  for (const [prefix, featureId] of prefixMatches) {
    if (normalized.startsWith(prefix)) {
      return featureId;
    }
  }

  return null;
}

