async function fetchGuildInviteSnapshot(guild: any): Promise<Map<string, InviteSnapshot> | null> {
  try {
    const invites = await guild.invites.fetch();
    const snapshot = new Map<string, InviteSnapshot>();
    invites.forEach((invite: any) => {
      if (!invite?.code) return;
      snapshot.set(invite.code, {
        uses: invite.uses || 0,
        inviterId: invite.inviter?.id || null,
      });
    });
    return snapshot;
  } catch (e) {
    return null;
  }
}

async function refreshGuildInviteSnapshot(guild: any): Promise<void> {
  const snapshot = await fetchGuildInviteSnapshot(guild);
  if (snapshot) {
    guildInviteSnapshots.set(guild.id, snapshot);
  }
}

async function fetchGuildVanitySnapshot(guild: any): Promise<VanitySnapshot | null> {
  try {
    const vanityData = await guild.fetchVanityData();
    const code = vanityData?.code ? String(vanityData.code).toLowerCase() : null;
    const uses = Number(vanityData?.uses || 0);
    return { code, uses: Number.isFinite(uses) ? uses : 0 };
  } catch {
    return null;
  }
}

async function refreshGuildVanitySnapshot(guild: any): Promise<void> {
  const snapshot = await fetchGuildVanitySnapshot(guild);
  if (snapshot) {
    guildVanitySnapshots.set(guild.id, snapshot);
  }
}

function extractInviteCodesFromContent(content: string): string[] {
  const source = String(content || "");
  const regex = /(?:discord\.gg|discord(?:app)?\.com\/invite)\/([a-zA-Z0-9-]+)/gi;
  const codes = new Set<string>();
  let match: RegExpExecArray | null = null;

  while ((match = regex.exec(source)) !== null) {
    const code = (match[1] || "").trim().toLowerCase();
    if (code) {
      codes.add(code);
    }
  }

  return Array.from(codes);
}

function storeModmailCopyContent(messageId: string, content: string, attachments?: string[]) {
  // Clean up old entries if cache is too large
  if (modmailCopyCache.size >= MAX_COPY_CACHE_ENTRIES) {
    const firstKey = modmailCopyCache.keys().next().value;
    if (firstKey) modmailCopyCache.delete(firstKey);
  }
  modmailCopyCache.set(messageId, { content, attachments });
}

function getModmailCopyContent(messageId: string): ModmailCopyData | undefined {
  return modmailCopyCache.get(messageId);
}

function clampEmbedDescription(value: string, max = 4000): string {
  const text = (value || "").trim();
  if (!text) return "(No text content)";
  if (text.length <= max) return text;
  return `${text.substring(0, max - 3)}...`;
}

function toArray<T = any>(value: any): T[] {
  if (!value) return [];
  if (Array.isArray(value)) return value;
  try {
    return Array.from(value as Iterable<T>);
  } catch {
    return [];
  }
}

function uniqueStrings(values: string[]): string[] {
  return Array.from(new Set((values || []).filter(Boolean)));
}

function formatUrlListForField(urls: string[], maxLength = 1000): string {
  if (!urls || urls.length === 0) return "";

  const lines: string[] = [];
  for (const url of urls) {
    const candidate = lines.length === 0 ? url : `${lines.join("\n")}\n${url}`;
    if (candidate.length > maxLength) break;
    lines.push(url);
  }

  const remaining = urls.length - lines.length;
  if (remaining > 0) {
    const suffix = `\n...and ${remaining} more`;
    const base = lines.join("\n");
    return `${base.substring(0, Math.max(0, maxLength - suffix.length))}${suffix}`;
  }

  return lines.join("\n");
}

function extractAttachmentObjects(source: any): Array<{ url: string; proxyUrl?: string; contentType?: string }> {
  if (!source?.attachments) return [];

  const attachmentsRaw = source.attachments;
  const entries = Array.isArray(attachmentsRaw)
    ? attachmentsRaw
    : typeof attachmentsRaw?.values === "function"
      ? Array.from(attachmentsRaw.values())
      : typeof attachmentsRaw === "object"
        ? Object.values(attachmentsRaw)
        : [];

  return entries
    .map((item: any) => ({
      url: (item?.url || item?.proxyURL || "").trim(),
      proxyUrl: (item?.proxyURL || "").trim() || undefined,
      contentType: item?.contentType,
    }))
    .filter((item: any) => !!item.url);
}

function extractEmbedMediaUrls(embeds: any): string[] {
  const items = toArray<any>(embeds);
  const urls: string[] = [];

  for (const embed of items) {
    const candidates = [
      embed?.image?.url,
      embed?.thumbnail?.url,
      embed?.video?.url,
      embed?.url,
    ];

    for (const candidate of candidates) {
      const url = (candidate || "").trim();
      if (url) urls.push(url);
    }
  }

  return uniqueStrings(urls);
}

async function downloadAttachmentsAsFiles(
  attachmentsInput: any
): Promise<Array<{ builder: AttachmentBuilder; name: string; isImage: boolean }>> {
  const attachments: Array<{ url: string; proxyUrl?: string; contentType?: string }> =
    Array.isArray(attachmentsInput)
      ? attachmentsInput
      : typeof attachmentsInput?.values === "function"
        ? Array.from(attachmentsInput.values())
        : typeof attachmentsInput === "object" && attachmentsInput !== null
          ? Object.values(attachmentsInput)
          : [];

  const results: Array<{ builder: AttachmentBuilder; name: string; isImage: boolean }> = [];
  for (const att of attachments) {
    const primaryUrl = ((att as any)?.url || (att as any)?.proxyURL || "").trim();
    const proxyUrl = ((att as any)?.proxyUrl || (att as any)?.proxyURL || "").trim();
    const contentType = ((att as any)?.contentType || "") as string;
    const candidateUrls = uniqueStrings([primaryUrl, proxyUrl]);
    for (const candidateUrl of candidateUrls) {
      if (!candidateUrl) continue;

      try {
        const timeoutSignal = typeof (AbortSignal as any)?.timeout === "function"
          ? (AbortSignal as any).timeout(12000)
          : undefined;

        const response = timeoutSignal
          ? await fetch(candidateUrl, { signal: timeoutSignal } as any)
          : await fetch(candidateUrl);

        if (!response.ok) continue;
        const arrayBuffer = await response.arrayBuffer();
        if (arrayBuffer.byteLength === 0) continue;
        const buffer = Buffer.from(arrayBuffer);
        const rawName = candidateUrl.split('/').pop()?.split('?')[0] || 'attachment';
        const name = rawName.replace(/[^a-zA-Z0-9._-]/g, '_') || 'attachment';
        const isImage = /\.(png|jpe?g|gif|webp|bmp)$/i.test(name) || contentType.startsWith('image/');
        results.push({ builder: new AttachmentBuilder(buffer, { name }), name, isImage });
        break;
      } catch {
        // try next candidate URL
      }
    }
  }
  return results;
}

function pickFirstImageUrl(attachments: Array<{ url: string; proxyUrl?: string; contentType?: string }>, embedMediaUrls: string[]): string | undefined {
  const imageAttachment = attachments.find((item) => {
    const type = (item.contentType || "").toLowerCase();
    return type.startsWith("image/") || /\.(png|jpe?g|gif|webp|bmp|svg)(\?.*)?$/i.test(item.url);
  });
  if (imageAttachment?.url) return imageAttachment.url;

  return embedMediaUrls.find((url) => /\.(png|jpe?g|gif|webp|bmp|svg)(\?.*)?$/i.test(url));
}

function isForwardedPlaceholderText(value: string): boolean {
  const normalized = (value || "").trim().toLowerCase();
  if (!normalized) return false;

  return normalized === "forwarded message"
    || normalized === "forwarded messages"
    || normalized === "fw"
    || normalized === "fwd";
}

async function tryFetchReferencedMessage(message: any): Promise<any | undefined> {
  if (!message?.reference) return undefined;

  try {
    if (typeof message.fetchReference === "function") {
      return await message.fetchReference();
    }

    const refId = message.reference?.messageId;
    if (refId && message.channel?.messages?.fetch) {
      return await message.channel.messages.fetch(refId);
    }
  } catch {
    // ignore
  }

  return undefined;
}

function buildDMRelayDescriptionFromText(text: string, isForwarded: boolean): string {
  const normalized = (text || "").trim();
  if (!normalized) {
    return isForwarded
      ? "No preview text was provided by Discord for this forward."
      : "(No text content)";
  }

  return clampEmbedDescription(normalized);
}

async function buildDMRelayPayload(message: any): Promise<{ description: string; plainText: string; attachmentUrls: string[]; imageUrl?: string; rawAttachments: Array<{ url: string; proxyUrl?: string; contentType?: string }> }> {
  const isForwarded = isForwardedDMMessage(message);
  const directContentRaw = (message.content || "").trim();
  const directContent = isForwarded && isForwardedPlaceholderText(directContentRaw) ? "" : directContentRaw;

  const snapshotMessage = (message as any).messageSnapshots?.[0]?.message;
  const snapshotContent = (snapshotMessage?.content || "").trim();
  const referencedMessage = isForwarded ? await tryFetchReferencedMessage(message) : undefined;
  const referencedContentRaw = (referencedMessage?.content || "").trim();
  const referencedContent = isForwarded && isForwardedPlaceholderText(referencedContentRaw) ? "" : referencedContentRaw;

  let plainText = directContent || snapshotContent || referencedContent;

  if (!plainText && isForwarded) {
    const embedSources = toArray<any>(snapshotMessage?.embeds).length > 0
      ? toArray<any>(snapshotMessage?.embeds)
      : toArray<any>(referencedMessage?.embeds).length > 0
        ? toArray<any>(referencedMessage?.embeds)
        : toArray<any>(message.embeds);

    const embedPreviewLines = embedSources
      .slice(0, 3)
      .map((embed: any) => {
        const title = (embed?.title || "").trim();
        const description = (embed?.description || "").trim();
        const url = (embed?.url || "").trim();
        const pieces = [title, description, url].filter(Boolean);
        if (pieces.length === 0) return "";
        return pieces.join(" — ");
      })
      .filter(Boolean);

    if (embedPreviewLines.length > 0) {
      plainText = embedPreviewLines.join("\n");
    }
  }

  const description = buildDMRelayDescriptionFromText(plainText, isForwarded);

  const directAttachments = extractAttachmentObjects(message);
  const snapshotAttachments = extractAttachmentObjects(snapshotMessage);
  const referencedAttachments = extractAttachmentObjects(referencedMessage);
  const allAttachments = [...directAttachments, ...snapshotAttachments, ...referencedAttachments];

  const snapshotEmbedMedia = extractEmbedMediaUrls(snapshotMessage?.embeds);
  const referenceEmbedMedia = extractEmbedMediaUrls(referencedMessage?.embeds);
  const messageEmbedMedia = extractEmbedMediaUrls(message.embeds);
  const attachmentUrls = uniqueStrings([
    ...allAttachments.map((a) => a.url),
    ...snapshotEmbedMedia,
    ...referenceEmbedMedia,
    ...messageEmbedMedia,
  ]);

  const imageUrl = pickFirstImageUrl(allAttachments, [...snapshotEmbedMedia, ...referenceEmbedMedia, ...messageEmbedMedia]);

  return { description, plainText, attachmentUrls, imageUrl, rawAttachments: allAttachments };
}

function isForwardedDMMessage(message: any): boolean {
  const hasReference = !!message?.reference;
  const hasSnapshot = toArray((message as any)?.messageSnapshots).length > 0;
  const contentText = (message?.content || "").trim();
  const hasForwardedPlaceholder = isForwardedPlaceholderText(contentText);

  // Only treat as forwarded when Discord includes forwarded snapshot data,
  // or when content is the explicit forwarded placeholder text.
  // Normal reply messages can include a reference and should still relay.
  return hasSnapshot || (hasReference && hasForwardedPlaceholder);
}

function cacheDMMessage(userId: string, message: any) {
  if (!message.author || message.author.bot) return;
  
  const cached: CachedDMMessage = {
    id: message.id,
    content: message.content || "",
    authorId: message.author.id,
    authorTag: message.author.tag,
    authorAvatar: message.author.displayAvatarURL(),
    timestamp: Date.now(),
  };
  
  let userCache = dmMessageCache.get(userId) || [];
  userCache.push(cached);
  if (userCache.length > MAX_CACHED_MESSAGES_PER_USER) {
    userCache = userCache.slice(-MAX_CACHED_MESSAGES_PER_USER);
  }
  dmMessageCache.set(userId, userCache);
}

function getCachedDMMessage(userId: string, messageId: string): CachedDMMessage | undefined {
  const userCache = dmMessageCache.get(userId);
  if (!userCache) return undefined;
  return userCache.find(m => m.id === messageId);
}

function getPendingModmailTypingNoticeKey(threadId: string, userId: string): string {
  return `${threadId}:${userId}`;
}

async function getOpenModmailThreadForParticipant(userId: string): Promise<{ thread: any; isAddedMember: boolean }> {
  const directThread = await storage.getOpenModmailThreadByUserId(userId).catch(() => undefined);
  if (directThread && directThread.channelId && directThread.status === "open") {
    return { thread: directThread, isAddedMember: false };
  }

  const addedMemberThread = await storage.getOpenModmailThreadByAddedMember(userId).catch(() => undefined);
  if (addedMemberThread && addedMemberThread.channelId && addedMemberThread.status === "open") {
    return { thread: addedMemberThread, isAddedMember: true };
  }

  return { thread: undefined, isAddedMember: false };
}

function rememberRecentlyRemovedModmailParticipant(
  userId: string,
  entry: Omit<RecentRemovedModmailParticipant, "removedAt">
): void {
  recentlyRemovedModmailParticipants.set(userId, { ...entry, removedAt: Date.now() });
}

function getRecentlyRemovedModmailParticipant(userId: string): RecentRemovedModmailParticipant | undefined {
  const entry = recentlyRemovedModmailParticipants.get(userId);
  if (!entry) return undefined;

  if (Date.now() - entry.removedAt > RECENTLY_REMOVED_MODMAIL_TTL_MS) {
    recentlyRemovedModmailParticipants.delete(userId);
    return undefined;
  }

  return entry;
}

function clearPendingModmailTypingNotice(key: string): void {
  const existing = pendingModmailTypingNotices.get(key);
  if (!existing) return;
  clearTimeout(existing.timeout);
  pendingModmailTypingNotices.delete(key);
}

function schedulePendingModmailTypingNoticeCleanup(key: string, channelId: string, messageId: string): NodeJS.Timeout {
  return setTimeout(async () => {
    const current = pendingModmailTypingNotices.get(key);
    if (!current || current.messageId !== messageId) return;

    pendingModmailTypingNotices.delete(key);
    try {
      const staffChannel = await client.channels.fetch(channelId).catch(() => null);
      if (staffChannel && "messages" in staffChannel) {
        const typingMessage = await (staffChannel as any).messages.fetch(messageId).catch(() => null);
        await typingMessage?.delete().catch(() => undefined);
      }
    } catch {
      // ignore stale typing notice cleanup failures
    }
  }, MODMAIL_TYPING_NOTICE_TTL_MS);
}

function buildModmailActionRow(threadId: string, dmMessageId: string, authorId: string) {
  const actionMenu = new StringSelectMenuBuilder()
    .setCustomId(`modmail_action_${threadId}_${dmMessageId}_${authorId}`)
    .setPlaceholder("Select an action...")
    .addOptions(
      new StringSelectMenuOptionBuilder()
        .setLabel("Send Message")
        .setDescription("Show this message content for copy/paste")
        .setValue("send_message")
        .setEmoji("📋"),
      new StringSelectMenuOptionBuilder()
        .setLabel("Send Message In DMs")
        .setDescription("DM this message content to yourself")
        .setValue("send_message_dm")
        .setEmoji("✉️"),
      new StringSelectMenuOptionBuilder()
        .setLabel("Toggle Member")
        .setDescription("Add or remove a member from this ticket")
        .setValue("toggle_member")
        .setEmoji("👥"),
      new StringSelectMenuOptionBuilder()
        .setLabel("Request A Role")
        .setDescription("Create a role request from this ticket")
        .setValue("request_role")
        .setEmoji("🛡️"),
      new StringSelectMenuOptionBuilder()
        .setLabel("User Modlogs")
        .setDescription("Show modlogs for this user")
        .setValue("user_modlogs")
        .setEmoji("📚"),
      new StringSelectMenuOptionBuilder()
        .setLabel("Modmail Logs")
        .setDescription("Show modmail logs for this user")
        .setValue("user_modmail_logs")
        .setEmoji("📝")
    );

  return new ActionRowBuilder<StringSelectMenuBuilder>().addComponents(actionMenu);
}

client.on("typingStart", async (typing) => {
  if (!typing || typing.channel?.type !== ChannelType.DM) return;
  if (typing.user?.bot) return;

  try {
    const userId = String(typing.user.id || "").trim();
    if (!userId) return;

    const { thread, isAddedMember } = await getOpenModmailThreadForParticipant(userId);
    if (!thread || !thread.channelId || thread.status !== "open") return;

    const staffChannel = await client.channels.fetch(thread.channelId).catch(() => null);
    if (!staffChannel || !("send" in staffChannel)) return;

    const noticeKey = getPendingModmailTypingNoticeKey(thread.id, userId);
    const existingNotice = pendingModmailTypingNotices.get(noticeKey);
    if (existingNotice) {
      clearTimeout(existingNotice.timeout);
      existingNotice.timeout = schedulePendingModmailTypingNoticeCleanup(noticeKey, existingNotice.channelId, existingNotice.messageId);
      pendingModmailTypingNotices.set(noticeKey, existingNotice);
      return;
    }

    const typingEmbed = new EmbedBuilder()
      .setColor(0xf0b232)
      .setAuthor({
        name: typing.user.tag || typing.user.username || "Unknown User",
        ...(typing.user.displayAvatarURL() ? { iconURL: typing.user.displayAvatarURL() || undefined } : {}),
      })
      .setDescription("The user is typing... ✍️")
      .setTimestamp();

    if (isAddedMember) {
      typingEmbed.setFooter({ text: "Added Member" });
    }

    const typingMessage = await (staffChannel as any).send({ embeds: [typingEmbed] }).catch(() => null);
    if (!typingMessage?.id) return;

    pendingModmailTypingNotices.set(noticeKey, {
      channelId: thread.channelId,
      messageId: typingMessage.id,
      timeout: schedulePendingModmailTypingNoticeCleanup(noticeKey, thread.channelId, typingMessage.id),
    });
  } catch {
    // ignore DM typing relay failures
  }
});

