type RequestPingTarget =
  | "payout_requests"
  | "ban_requests"
  | "unban_requests"
  | "kick_requests"
  | "inactivity_submissions"
  | "quiz_submissions"
  | "staff_submissions"
  | "role_requests"
  | "pro_role_requests"
  | "promotion_demotion_requests"
  | "modmail_tickets"
  | "appeal_tickets";

const REQUEST_PING_TARGET_LABELS: Record<RequestPingTarget, string> = {
  payout_requests: "Payout Requests",
  ban_requests: "Ban Requests",
  unban_requests: "Unban Requests",
  kick_requests: "Kick Requests",
  inactivity_submissions: "Inactivity Submissions",
  quiz_submissions: "Staff Intro Quiz Submissions",
  staff_submissions: "Staff Application Submissions",
  role_requests: "Role Requests",
  pro_role_requests: "Pro Role Requests",
  promotion_demotion_requests: "Promotion/Demotion Requests",
  modmail_tickets: "Modmail Tickets",
  appeal_tickets: "Appeal Tickets",
};

function getRequestPingRolesMapFromGuildConfig(config?: any): Record<string, string[]> {
  const root = parseJsonObject(config?.customCategoryPings);
  const raw = root?.__requestPingRoleIds;
  if (!raw || typeof raw !== "object") return {};

  const result: Record<string, string[]> = {};
  for (const [target, value] of Object.entries(raw)) {
    result[target] = normalizeStringArray(value);
  }
  return result;
}

function getRequestPingRoleNamesMapFromGuildConfig(config?: any): Record<string, string[]> {
  const root = parseJsonObject(config?.customCategoryPings);
  const raw = root?.__requestPingRoleNames;
  if (!raw || typeof raw !== "object") return {};

  const result: Record<string, string[]> = {};
  for (const [target, value] of Object.entries(raw)) {
    result[target] = normalizeStringArray(value);
  }
  return result;
}

function getRequestPingRoleIdsFromGuildConfig(config: any, target: RequestPingTarget): string[] {
  const map = getRequestPingRolesMapFromGuildConfig(config);
  return map[target] || [];
}

function getRequestPingRoleNamesFromGuildConfig(config: any, target: RequestPingTarget): string[] {
  const map = getRequestPingRoleNamesMapFromGuildConfig(config);
  return map[target] || [];
}

function formatRequestPingRolesForGuild(config: any, target: RequestPingTarget, guild: any): string {
  const roleIds = getRequestPingRoleIdsFromGuildConfig(config, target);
  const roleNames = getRequestPingRoleNamesFromGuildConfig(config, target);

  if (!guild) {
    return roleNames.length > 0 ? roleNames.join(", ") : roleIds.length > 0 ? roleIds.join(", ") : "None";
  }

  const parts: string[] = [];
  const seen = new Set<string>();

  for (const roleId of roleIds) {
    const role = guild.roles.cache.get(roleId);
    if (role) {
      parts.push(`<@&${role.id}>`);
      seen.add(role.name.trim().toLowerCase());
      continue;
    }

    let sourceRoleName: string | null = null;
    for (const otherGuild of client.guilds.cache.values()) {
      const otherRole = otherGuild.roles.cache.get(roleId);
      if (otherRole?.name) {
        sourceRoleName = otherRole.name;
        break;
      }
    }

    if (sourceRoleName) {
      const localMatch = guild.roles.cache.find((entry: any) => String(entry.name || "").trim().toLowerCase() === sourceRoleName!.trim().toLowerCase());
      if (localMatch) {
        parts.push(`<@&${localMatch.id}>`);
      } else if (!seen.has(sourceRoleName.trim().toLowerCase())) {
        parts.push(sourceRoleName);
      }
      seen.add(sourceRoleName.trim().toLowerCase());
    }
  }

  for (const roleName of roleNames) {
    const trimmed = roleName.trim();
    if (!trimmed) continue;
    const role = guild.roles.cache.find((entry: any) => String(entry.name || "").trim().toLowerCase() === trimmed.toLowerCase());
    if (role) {
      if (!parts.includes(`<@&${role.id}>`)) {
        parts.push(`<@&${role.id}>`);
      }
      seen.add(trimmed.toLowerCase());
      continue;
    }

    if (!seen.has(trimmed.toLowerCase())) {
      parts.push(trimmed);
      seen.add(trimmed.toLowerCase());
    }
  }

  return parts.length > 0 ? parts.join(", ") : "None";
}

function writeRequestPingRolesToConfig(
  existingCustomCategoryPings: string | null | undefined,
  target: RequestPingTarget,
  roleIds: string[],
  roleNames?: string[],
): string {
  const root = parseJsonObject(existingCustomCategoryPings);
  const existingMap = typeof root.__requestPingRoleIds === "object" && root.__requestPingRoleIds
    ? root.__requestPingRoleIds
    : {};
  const existingNamesMap = typeof root.__requestPingRoleNames === "object" && root.__requestPingRoleNames
    ? root.__requestPingRoleNames
    : {};
  root.__requestPingRoleIds = {
    ...existingMap,
    [target]: roleIds,
  };
  root.__requestPingRoleNames = {
    ...existingNamesMap,
    [target]: roleNames || [],
  };
  return JSON.stringify(root);
}

async function getSyncedRequestPingConfig(target: RequestPingTarget, baseGuildId: string): Promise<{ roleIds: string[]; roleNames: string[] }> {
  const currentConfig = await storage.getGuildConfig(baseGuildId).catch(() => undefined);
  const currentRoleIds = getRequestPingRoleIdsFromGuildConfig(currentConfig, target);
  const currentRoleNames = getRequestPingRoleNamesFromGuildConfig(currentConfig, target);
  if (currentRoleIds.length > 0 || currentRoleNames.length > 0) {
    return { roleIds: currentRoleIds, roleNames: currentRoleNames };
  }

  for (const guild of client.guilds.cache.values()) {
    if (guild.id === baseGuildId) continue;
    const config = await storage.getGuildConfig(guild.id).catch(() => undefined);
    const roleIds = getRequestPingRoleIdsFromGuildConfig(config, target);
    const roleNames = getRequestPingRoleNamesFromGuildConfig(config, target);
    if (roleIds.length > 0 || roleNames.length > 0) {
      return { roleIds, roleNames };
    }
  }

  return { roleIds: [], roleNames: [] };
}

async function writeSyncedRequestPingRoles(target: RequestPingTarget, roleIds: string[], roleNames: string[]): Promise<void> {
  const guilds = Array.from(client.guilds.cache.values());
  if (guilds.length === 0) return;

  await Promise.all(guilds.map(async (guild) => {
    const config = await storage.getGuildConfig(guild.id).catch(() => undefined);
    await storage.upsertGuildConfig({
      guildId: guild.id,
      customCategoryPings: writeRequestPingRolesToConfig(config?.customCategoryPings, target, roleIds, roleNames),
    });
  }));
}

interface WelcomeSetupConfig {
  channelId: string | null;
  message: string;
  author: string;
  authorIcon: string;
  footer: string;
  footerIcon: string;
  color: number;
}

const DEFAULT_WELCOME_SETUP: WelcomeSetupConfig = {
  channelId: null,
  message: "Welcome {user} to **{server}**!",
  author: "Welcome",
  authorIcon: "",
  footer: "Enjoy your stay",
  footerIcon: "",
  color: 0x57f287,
};

function parseHexColorInput(value?: string | null): number | null {
  const raw = (value || "").trim().replace(/^#/, "");
  if (!raw) return null;
  if (!/^[0-9a-fA-F]{6}$/.test(raw)) return null;
  const parsed = parseInt(raw, 16);
  if (!Number.isFinite(parsed)) return null;
  return parsed;
}

function getWelcomeSetupFromGuildConfig(config?: any): WelcomeSetupConfig {
  const root = parseJsonObject(config?.customCategoryPings);
  const raw = root?.__welcomeSetup || {};

  const color = typeof raw?.color === "number" && raw.color >= 0 && raw.color <= 0xffffff
    ? raw.color
    : DEFAULT_WELCOME_SETUP.color;

  return {
    channelId: typeof raw?.channelId === "string" && raw.channelId.trim().length > 0 ? raw.channelId.trim() : null,
    message: typeof raw?.message === "string" && raw.message.trim().length > 0 ? raw.message : DEFAULT_WELCOME_SETUP.message,
    author: typeof raw?.author === "string" ? raw.author : DEFAULT_WELCOME_SETUP.author,
    authorIcon: typeof raw?.authorIcon === "string" ? raw.authorIcon : DEFAULT_WELCOME_SETUP.authorIcon,
    footer: typeof raw?.footer === "string" ? raw.footer : DEFAULT_WELCOME_SETUP.footer,
    footerIcon: typeof raw?.footerIcon === "string" ? raw.footerIcon : DEFAULT_WELCOME_SETUP.footerIcon,
    color,
  };
}

function writeWelcomeSetupToConfig(
  existingCustomCategoryPings: string | null | undefined,
  updates: Partial<WelcomeSetupConfig>,
): string {
  const root = parseJsonObject(existingCustomCategoryPings);
  const current = getWelcomeSetupFromGuildConfig({ customCategoryPings: existingCustomCategoryPings });
  root.__welcomeSetup = {
    ...current,
    ...updates,
  };
  return JSON.stringify(root);
}

function buildWelcomeJoinEmbed(member: any, setup: WelcomeSetupConfig): EmbedBuilder {
  const joinDate = member?.joinedAt instanceof Date ? member.joinedAt : null;
  const createdDate = member?.user?.createdAt instanceof Date ? member.user.createdAt : null;
  const joinedAtDisplay = joinDate ? joinDate.toLocaleString() : "Unknown";
  const createdAtDisplay = createdDate ? createdDate.toLocaleString() : "Unknown";

  const templateValues: Record<string, string> = {
    user: `<@${member.id}>`,
    mention: `<@${member.id}>`,
    username: member?.user?.username || "Unknown User",
    displayname: member?.displayName || member?.user?.username || "Unknown User",
    userid: member?.id || "",
    server: member?.guild?.name || "Unknown Server",
    serverid: member?.guild?.id || "",
    membercount: String(member?.guild?.memberCount || 0),
    member_count: String(member?.guild?.memberCount || 0),
    joinedat: joinedAtDisplay,
    joined_at: joinedAtDisplay,
    createdat: createdAtDisplay,
    created_at: createdAtDisplay,
  };

  const renderedMessage = Object.entries(templateValues).reduce((output, [key, value]) => {
    return output.replace(new RegExp(`\\{${key}\\}`, "gi"), value);
  }, setup.message || DEFAULT_WELCOME_SETUP.message);

  const embed = new EmbedBuilder()
    .setDescription(renderedMessage)
    .setColor(setup.color || DEFAULT_WELCOME_SETUP.color)
    .setTimestamp();

  if ((setup.author || "").trim().length > 0) {
    if ((setup.authorIcon || "").trim().length > 0 && isHttpUrl(setup.authorIcon)) {
      embed.setAuthor({ name: setup.author, iconURL: setup.authorIcon.trim() });
    } else {
      embed.setAuthor({ name: setup.author });
    }
  }

  if ((setup.footer || "").trim().length > 0) {
    if ((setup.footerIcon || "").trim().length > 0 && isHttpUrl(setup.footerIcon)) {
      embed.setFooter({ text: setup.footer, iconURL: setup.footerIcon.trim() });
    } else {
      embed.setFooter({ text: setup.footer });
    }
  }

  return embed;
}

type AutoRoleMode = "add" | "remove";

interface AutoRoleRuleConfig {
  id: string;
  roleId: string;
  type: AutoRoleMode;
  delayMinutes: number;
}

type ReactionRoleMode = "both" | "add_only" | "remove_only";
type ReactionRolePickerStyle = "reactions" | "buttons" | "dropdown";

interface ReactionRoleEntryConfig {
  id: string;
  emoji: string;
  roleId: string;
  mode: ReactionRoleMode;
}

interface ReactionRoleSetupConfig {
  name: string;
  channelId: string | null;
  useExistingMessage: boolean;
  existingMessageInput: string;
  messageId: string | null;
  pickerStyle: ReactionRolePickerStyle;
  embedTitle: string;
  embedDescription: string;
  embedColor: string;
  authorName: string;
  authorIcon: string;
  footerText: string;
  footerIcon: string;
  thumbnailUrl: string;
  imageUrl: string;
  items: ReactionRoleEntryConfig[];
}

const DEFAULT_REACTION_ROLE_SETUP: ReactionRoleSetupConfig = {
  name: "Reaction Roles",
  channelId: null,
  useExistingMessage: false,
  existingMessageInput: "",
  messageId: null,
  pickerStyle: "reactions",
  embedTitle: "Reaction Roles",
  embedDescription: "Use the controls below to manage your roles.",
  embedColor: "5865f2",
  authorName: "",
  authorIcon: "",
  footerText: "",
  footerIcon: "",
  thumbnailUrl: "",
  imageUrl: "",
  items: [],
};

function getAutoRolesFromGuildConfig(config?: any): AutoRoleRuleConfig[] {
  const root = parseJsonObject(config?.customCategoryPings);
  const raw = Array.isArray(root?.__autoRoles) ? root.__autoRoles : [];

  return raw
    .map((entry: any) => {
      const roleId = typeof entry?.roleId === "string" ? entry.roleId.trim() : "";
      const rawType = typeof entry?.type === "string" ? entry.type.toLowerCase() : "add";
      const delayMinutes = Number(entry?.delayMinutes || 0);
      if (!roleId) return null;
      return {
        id: typeof entry?.id === "string" && entry.id.trim().length > 0 ? entry.id.trim() : `${roleId}-${rawType}`,
        roleId,
        type: rawType === "remove" ? "remove" : "add",
        delayMinutes: Number.isFinite(delayMinutes) ? Math.max(0, Math.min(10080, Math.round(delayMinutes))) : 0,
      } as AutoRoleRuleConfig;
    })
    .filter((entry): entry is AutoRoleRuleConfig => !!entry);
}

function getReactionRoleSetupFromGuildConfig(config?: any): ReactionRoleSetupConfig {
  const root = parseJsonObject(config?.customCategoryPings);
  const raw = root?.__reactionRoleSetup;
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    return { ...DEFAULT_REACTION_ROLE_SETUP };
  }

  const items = Array.isArray(raw.items)
    ? raw.items
        .map((entry: any) => {
          const emoji = typeof entry?.emoji === "string" ? entry.emoji.trim() : "";
          const roleId = typeof entry?.roleId === "string" ? entry.roleId.trim() : "";
          const rawMode = typeof entry?.mode === "string" ? entry.mode.toLowerCase() : "both";
          if (!roleId) return null;
          return {
            id: typeof entry?.id === "string" && entry.id.trim().length > 0 ? entry.id.trim() : `${roleId}-${emoji || "role"}`,
            emoji,
            roleId,
            mode: rawMode === "add_only" || rawMode === "remove_only" ? rawMode : "both",
          } as ReactionRoleEntryConfig;
        })
        .filter((entry: ReactionRoleEntryConfig | null): entry is ReactionRoleEntryConfig => !!entry)
    : [];

  return {
    name: typeof raw.name === "string" && raw.name.trim().length > 0 ? raw.name.trim() : DEFAULT_REACTION_ROLE_SETUP.name,
    channelId: typeof raw.channelId === "string" && raw.channelId.trim().length > 0 ? raw.channelId.trim() : null,
    useExistingMessage: raw.useExistingMessage === true,
    existingMessageInput: typeof raw.existingMessageInput === "string" ? raw.existingMessageInput : "",
    messageId: typeof raw.messageId === "string" && raw.messageId.trim().length > 0 ? raw.messageId.trim() : null,
    pickerStyle: raw.pickerStyle === "buttons" || raw.pickerStyle === "dropdown" ? raw.pickerStyle : "reactions",
    embedTitle: typeof raw.embedTitle === "string" && raw.embedTitle.trim().length > 0 ? raw.embedTitle : DEFAULT_REACTION_ROLE_SETUP.embedTitle,
    embedDescription: typeof raw.embedDescription === "string" && raw.embedDescription.trim().length > 0 ? raw.embedDescription : DEFAULT_REACTION_ROLE_SETUP.embedDescription,
    embedColor: typeof raw.embedColor === "string" ? raw.embedColor.replace(/[^0-9a-f]/gi, "").slice(0, 6) : DEFAULT_REACTION_ROLE_SETUP.embedColor,
    authorName: typeof raw.authorName === "string" ? raw.authorName.trim() : DEFAULT_REACTION_ROLE_SETUP.authorName,
    authorIcon: typeof raw.authorIcon === "string" ? raw.authorIcon.trim() : DEFAULT_REACTION_ROLE_SETUP.authorIcon,
    footerText: typeof raw.footerText === "string" ? raw.footerText.trim() : DEFAULT_REACTION_ROLE_SETUP.footerText,
    footerIcon: typeof raw.footerIcon === "string" ? raw.footerIcon.trim() : DEFAULT_REACTION_ROLE_SETUP.footerIcon,
    thumbnailUrl: typeof raw.thumbnailUrl === "string" ? raw.thumbnailUrl.trim() : DEFAULT_REACTION_ROLE_SETUP.thumbnailUrl,
    imageUrl: typeof raw.imageUrl === "string" ? raw.imageUrl.trim() : DEFAULT_REACTION_ROLE_SETUP.imageUrl,
    items,
  };
}

function normalizeReactionEmojiInput(value?: string | null): string {
  const trimmed = String(value || "").trim();
  if (!trimmed) return "";

  const customMatch = trimmed.match(/^<a?:([^:>]+):(\d{17,20})>$/);
  if (customMatch) {
    return `${customMatch[1]}:${customMatch[2]}`;
  }

  const emojiById = trimmed.match(/^(\d{17,20})$/);
  if (emojiById?.[1]) {
    const emoji = client.emojis.cache.get(emojiById[1]);
    if (emoji?.name) {
      return `${emoji.name}:${emoji.id}`;
    }
  }

  return trimmed;
}

function getReactionEmojiKey(reaction: any): string {
  const emoji = reaction?.emoji;
  if (!emoji) return "";
  if (emoji.id) {
    return `${emoji.name}:${emoji.id}`;
  }
  return String(emoji.name || "").trim();
}

function parseReactionRoleButtonCustomId(customId: string | null | undefined): { guildId: string; roleId: string; mode: ReactionRoleMode } | null {
  const match = String(customId || "").trim().match(/^rrbtn:(\d{17,20}):(\d{17,20}):(both|add_only|remove_only)$/);
  if (!match) return null;
  return {
    guildId: match[1],
    roleId: match[2],
    mode: match[3] as ReactionRoleMode,
  };
}

function buildReactionRoleSelectValue(roleId: string, mode: ReactionRoleMode): string {
  return `rr:${roleId}:${mode}`;
}

async function setReactionRoleState(
  member: any,
  roleId: string,
  shouldHaveRole: boolean,
  reason: string,
): Promise<"added" | "removed" | "unchanged" | "unavailable"> {
  if (!member?.guild || !roleId) return "unavailable";

  const me = member.guild.members.me ?? await member.guild.members.fetchMe().catch(() => null);
  if (!me?.permissions?.has(PermissionFlagsBits.ManageRoles)) return "unavailable";

  const role = member.guild.roles.cache.get(roleId);
  if (!role || role.position >= me.roles.highest.position) return "unavailable";

  const hasRole = member.roles?.cache?.has(role.id) === true;
  if (shouldHaveRole) {
    if (hasRole) return "unchanged";
    try {
      await member.roles.add(role.id, reason);
      return "added";
    } catch {
      return "unavailable";
    }
  }

  if (!hasRole) return "unchanged";
  try {
    await member.roles.remove(role.id, reason);
    return "removed";
  } catch {
    return "unavailable";
  }
}

async function applyReactionRoleButtonPress(member: any, roleId: string, mode: ReactionRoleMode): Promise<"added" | "removed" | "unchanged" | "unavailable"> {
  const currentlyHasRole = member?.roles?.cache?.has(roleId) === true;
  const shouldHaveRole = mode === "remove_only" ? false : mode === "add_only" ? true : !currentlyHasRole;
  return await setReactionRoleState(member, roleId, shouldHaveRole, `Reaction role ${mode === "remove_only" ? "remove" : currentlyHasRole && mode === "both" ? "toggle remove" : "toggle add"} via button`);
}

async function applyReactionRoleSelectMenu(interaction: any): Promise<void> {
  if (!await safeDeferReply(interaction, true)) return;

  const guild = interaction.guild;
  if (!guild) {
    await interaction.editReply({ content: "This role picker can only be used inside a server." });
    return;
  }

  const config = await storage.getGuildConfig(guild.id).catch(() => undefined);
  const setup = getReactionRoleSetupFromGuildConfig(config);
  const currentMessageId = String(setup.messageId || "").trim();
  if (setup.pickerStyle !== "dropdown" || !currentMessageId || currentMessageId !== String(interaction.message?.id || "").trim()) {
    await interaction.editReply({ content: "This role dropdown is no longer active. Repost the reaction role message from the dashboard." });
    return;
  }

  const member = await guild.members.fetch(interaction.user.id).catch(() => null);
  if (!member) {
    await interaction.editReply({ content: "Could not find your member record in this server." });
    return;
  }

  const selectedValues = new Set((interaction.values || []).map((value: string) => String(value)));
  const addedRoles: string[] = [];
  const removedRoles: string[] = [];

  for (const entry of setup.items.filter((item) => item.roleId)) {
    const role = guild.roles.cache.get(entry.roleId);
    const roleLabel = role?.name || entry.roleId;
    const optionValue = buildReactionRoleSelectValue(entry.roleId, entry.mode);

    let result: "added" | "removed" | "unchanged" | "unavailable" = "unchanged";
    if (selectedValues.has(optionValue)) {
      result = await setReactionRoleState(
        member,
        entry.roleId,
        entry.mode !== "remove_only",
        `Reaction role ${entry.mode === "remove_only" ? "remove" : "add"} via dropdown menu`,
      );
    } else if (entry.mode === "both") {
      result = await setReactionRoleState(member, entry.roleId, false, "Reaction role remove via dropdown menu");
    }

    if (result === "added") addedRoles.push(roleLabel);
    if (result === "removed") removedRoles.push(roleLabel);
  }

  const summaryLines: string[] = [];
  if (addedRoles.length > 0) summaryLines.push(`Added: ${addedRoles.join(", ")}`);
  if (removedRoles.length > 0) summaryLines.push(`Removed: ${removedRoles.join(", ")}`);

  await interaction.editReply({
    content: summaryLines.length > 0 ? `Updated your roles.\n${summaryLines.join("\n")}` : "No role changes were needed.",
  });
}

async function applyAutoRoleRule(member: any, rule: AutoRoleRuleConfig): Promise<void> {
  if (!member?.guild || !rule?.roleId) return;

  const me = member.guild.members.me ?? await member.guild.members.fetchMe().catch(() => null);
  if (!me?.permissions?.has(PermissionFlagsBits.ManageRoles)) return;

  const role = member.guild.roles.cache.get(rule.roleId);
  if (!role) return;
  if (role.position >= me.roles.highest.position) return;

  if (rule.type === "add") {
    if (!member.roles?.cache?.has(role.id)) {
      await member.roles.add(role.id, `Auto role on join${rule.delayMinutes > 0 ? ` after ${rule.delayMinutes} minute(s)` : ""}`).catch(() => undefined);
    }
    return;
  }

  if (member.roles?.cache?.has(role.id)) {
    await member.roles.remove(role.id, `Auto role removal on join${rule.delayMinutes > 0 ? ` after ${rule.delayMinutes} minute(s)` : ""}`).catch(() => undefined);
  }
}

async function applyConfiguredAutoRoles(member: any, guildConfig?: any): Promise<void> {
  if (!isDashboardFeatureEnabled(guildConfig, "auto-roles")) return;

  const autoRoles = getAutoRolesFromGuildConfig(guildConfig);
  if (autoRoles.length === 0) return;

  for (const rule of autoRoles) {
    if (rule.delayMinutes > 0) {
      setTimeout(async () => {
        try {
          const refreshedMember = await member.guild.members.fetch(member.id).catch(() => null);
          if (!refreshedMember) return;
          await applyAutoRoleRule(refreshedMember, rule);
        } catch {
          // ignore delayed auto role failures
        }
      }, rule.delayMinutes * 60 * 1000);
    } else {
      await applyAutoRoleRule(member, rule);
    }
  }
}

async function handleReactionRoleEvent(reaction: any, user: any, action: "add" | "remove"): Promise<void> {
  if (!user || user.bot) return;

  try {
    if (reaction?.partial) {
      await reaction.fetch().catch(() => null);
    }

    if (reaction?.message?.partial) {
      await reaction.message.fetch().catch(() => null);
    }

    const message = reaction?.message;
    const guild = message?.guild;
    if (!guild) return;

    const guildConfig = await storage.getGuildConfig(guild.id).catch(() => undefined);
    if (!isDashboardFeatureEnabled(guildConfig, "reaction-roles")) return;

    const setup = getReactionRoleSetupFromGuildConfig(guildConfig);
    if (setup.pickerStyle !== "reactions" || !setup.items.length) return;

    const configuredMessageId = String(setup.messageId || "").trim();
    if (!configuredMessageId || configuredMessageId !== String(message.id || "").trim()) {
      return;
    }

    const emojiKey = getReactionEmojiKey(reaction);
    if (!emojiKey) return;

    const matchingEntries = setup.items.filter((entry) => normalizeReactionEmojiInput(entry.emoji) === emojiKey);
    if (matchingEntries.length === 0) return;

    const member = await guild.members.fetch(user.id).catch(() => null);
    if (!member) return;

    const me = guild.members.me ?? await guild.members.fetchMe().catch(() => null);
    if (!me?.permissions?.has(PermissionFlagsBits.ManageRoles)) return;

    for (const entry of matchingEntries) {
      const role = guild.roles.cache.get(entry.roleId);
      if (!role) continue;
      if (role.position >= me.roles.highest.position) continue;

      if (action === "add") {
        if (entry.mode === "remove_only") {
          if (member.roles?.cache?.has(role.id)) {
            await member.roles.remove(role.id, `Reaction role remove via ${emojiKey}`).catch(() => undefined);
          }
        } else if (!member.roles?.cache?.has(role.id)) {
          await member.roles.add(role.id, `Reaction role add via ${emojiKey}`).catch(() => undefined);
        }
        continue;
      }

      if (entry.mode === "both" && member.roles?.cache?.has(role.id)) {
        await member.roles.remove(role.id, `Reaction role remove via ${emojiKey}`).catch(() => undefined);
      }
    }
  } catch (error) {
    console.log("Error in reaction role handler:", error);
  }
}

function buildStickyListEmbed(
  stickyConfigs: Record<string, StickyChannelConfig>,
  page: number,
  userId: string,
): { embed: EmbedBuilder; components: ActionRowBuilder<ButtonBuilder>[]; totalPages: number } {
  const entries = Object.entries(stickyConfigs)
    .sort((a, b) => a[0].localeCompare(b[0]));

  const itemsPerPage = 5;
  const totalPages = Math.max(1, Math.ceil(entries.length / itemsPerPage));
  const safePage = Math.min(Math.max(1, page), totalPages);
  const start = (safePage - 1) * itemsPerPage;
  const pageEntries = entries.slice(start, start + itemsPerPage);

  const description = pageEntries.length === 0
    ? "No sticky messages configured."
    : pageEntries.map(([channelId, sticky], index) => {
      const preview = sticky.message.length > 250 ? `${sticky.message.slice(0, 250)}…` : sticky.message;
      return [
        `**${start + index + 1}.** <#${channelId}>`,
        `Interval: ${sticky.interval} message(s)`,
        `Message: ${preview}`,
      ].join("\n");
    }).join("\n\n");

  const embed = new EmbedBuilder()
    .setColor(0x5865f2)
    .setTitle("Sticky Messages")
    .setDescription(description)
    .setFooter({ text: `Page ${safePage}/${totalPages} • Total stickies: ${entries.length}` })
    .setTimestamp();

  const components: ActionRowBuilder<ButtonBuilder>[] = [];
  if (totalPages > 1) {
    const row = new ActionRowBuilder<ButtonBuilder>().addComponents(
      new ButtonBuilder()
        .setCustomId(`sticky_list_${userId}_${safePage}_prev`)
        .setLabel("◀")
        .setStyle(ButtonStyle.Secondary)
        .setDisabled(safePage <= 1),
      new ButtonBuilder()
        .setCustomId(`sticky_list_${userId}_${safePage}_next`)
        .setLabel("▶")
        .setStyle(ButtonStyle.Secondary)
        .setDisabled(safePage >= totalPages),
    );
    components.push(row);
  }

  return { embed, components, totalPages };
}

function isRetimeAllowedAction(actionType: string): boolean {
  const lower = (actionType || "").toLowerCase();
  if (lower === "kick" || lower === "unban" || lower === "unmute") return false;
  return true;
}

const MODLOGS_ITEMS_PER_PAGE = 10;
const MODMAIL_LOGS_ITEMS_PER_PAGE = 10;
const APPEAL_LOGS_ITEMS_PER_PAGE = 10;

function buildModlogsEmbed(
  targetId: string,
  targetLabel: string,
  logs: any[],
  page: number,
  itemsPerPage = 10,
): { embed: EmbedBuilder; totalPages: number } {
  const filtered = logs.filter((entry) => parseActionTypeForLog(entry.actionType));
  const totalPages = Math.max(1, Math.ceil(filtered.length / itemsPerPage));
  const safePage = Math.min(Math.max(1, page), totalPages);
  const start = (safePage - 1) * itemsPerPage;
  const pageEntries = filtered.slice(start, start + itemsPerPage);

  const lines = pageEntries.map((entry, index) => {
    const type = parseActionTypeForLog(entry.actionType) || "Unknown";
    const caseId = buildSixDigitCaseId(entry, start + index + 1);
    const createdAtDate = entry.createdAt ? new Date(entry.createdAt) : null;
    const timestamp = createdAtDate
      ? `<t:${Math.floor(createdAtDate.getTime() / 1000)}:f> • <t:${Math.floor(createdAtDate.getTime() / 1000)}:R>`
      : "Unknown time";
    const moderator = entry.moderatorId ? `<@${entry.moderatorId}>` : "Unknown";
    const parsed = extractReasonAndDuration(entry.reason);
    const reason = parsed.reason;
    const shouldShowServer = ["ban", "kick", "mute", "timeout"].includes(String(entry.actionType || "").toLowerCase());
    const guildName = entry.guildId
      ? (client.guilds.cache.get(entry.guildId)?.name || `Guild ${entry.guildId}`)
      : "Unknown Guild";

    const details = [
      `**Case ID: ${caseId}**`,
      `Type: ${type}`,
      `User: <@${targetId}>`,
      `Moderator: ${moderator}`,
      ...(shouldShowServer ? [`Server: ${guildName}`] : []),
      `Reason: ${reason}`,
    ];

    if (parsed.duration) {
      const durationToken = parsed.duration.toLowerCase();
      if (durationToken === "permanent") {
        details.push("Duration: Permanent");
      } else {
        const durationMs = parseDurationMs(durationToken);
        if (durationMs && createdAtDate) {
          const expiresAt = new Date(createdAtDate.getTime() + durationMs);
          const expiresTs = Math.floor(expiresAt.getTime() / 1000);
          details.push(`Duration: ${parsed.duration} (until <t:${expiresTs}:f> • <t:${expiresTs}:R>)`);
        } else {
          details.push(`Duration: ${parsed.duration}`);
        }
      }
    }

    details.push(`Time: ${timestamp}`);
    return details.join("\n");
  });

  const embed = new EmbedBuilder()
    .setColor(0x5865f2)
    .setTitle(`Modlogs for (${targetLabel}) (Page ${safePage} of ${totalPages})`)
    .setDescription(lines.join("\n\n") || "No logs found for that user.")
    .setFooter({ text: `${filtered.length} total log${filtered.length === 1 ? "" : "s"}` });

  return { embed, totalPages };
}

