          const serverOption = interaction.options.getString("server") || "current";

          // Use "global" for cross-server synced entries, otherwise current guild
          const targetGuildId = serverOption === "global" ? "global" : interaction.guildId!;

          try {
            if (category === "modmail") {
              await storage.addModmailActivityEntries(targetGuildId, user.id, amount);
            } else if (category === "appeal") {
              await storage.addAppealActivityEntries(targetGuildId, user.id, amount);
            } else if (category === "invites") {
              await storage.addInviteActivityEntries(targetGuildId, user.id, amount);
            } else if (category === "staffreport") {
              await storage.addStaffReportEntries(targetGuildId, user.id, amount);
            } else if (category === "ban") {
              await storage.addBanActivityEntries(targetGuildId, user.id, amount);
            } else if (category === "unban") {
              await storage.addUnbanActivityEntries(targetGuildId, user.id, amount);
            } else if (category === "partnerships" || category === "staff_accepted" || category === "role_requests_reviewed" || category === "kick_requests_reviewed" || category === "accepted_semi_pros_pros") {
              await adjustExtraActivityCounterForScope(interaction.guildId!, category as ExtraActivityCounterKey, user.id, amount, serverOption === "global");
            } else if (category === "modban" || category === "kick" || category === "mute") {
              await storage.addModerationActivityEntries(targetGuildId, user.id, category, amount);
            }
          } catch (e) {
            console.log("Could not add activity entries:", e);
          }

          const categoryText = category === "ban"
            ? "ban request"
            : category === "modban"
              ? "moderation ban"
              : category === "kick"
                ? "moderation kick"
                : category === "mute"
                  ? "moderation mute"
                  : category === "unban"
                    ? "unban request"
                      : category === "invites"
                        ? "invite"
                    : category === "partnerships"
                      ? "partnership"
                    : category === "staff_accepted"
                      ? "accepted staff"
                    : category === "role_requests_reviewed"
                      ? "role request review"
                    : category === "kick_requests_reviewed"
                      ? "kick request review"
                    : category === "accepted_semi_pros_pros"
